const menuButton=document.querySelector('.menu'),navigation=document.querySelector('.hdr nav');menuButton.setAttribute('aria-expanded','false');menuButton.addEventListener('click',()=>{const open=menuButton.getAttribute('aria-expanded')!=='true';menuButton.setAttribute('aria-expanded',String(open));navigation.classList.toggle('open',open)});navigation.addEventListener('click',e=>{if(e.target.tagName==='A'){navigation.classList.remove('open');menuButton.setAttribute('aria-expanded','false')}});
document.querySelector('.faq').id='faq';
if(window.gsap&&!reduce){gsap.registerPlugin(ScrollTrigger);gsap.from('.word-top',{x:-120,opacity:0,duration:1.2,ease:'power3.out'});gsap.from('.word-bottom',{x:120,opacity:0,duration:1.2,ease:'power3.out'});gsap.from('.shot',{y:80,opacity:0,stagger:.08,duration:1,ease:'power3.out'});gsap.utils.toArray('.process-track article,.role-arc article,.eng-grid article').forEach(el=>gsap.from(el,{scrollTrigger:{trigger:el,start:'top 90%'},y:60,opacity:0,duration:.8}));gsap.to('.craft-wheel',{scrollTrigger:{trigger:'.craft-stage',start:'top bottom',end:'bottom top',scrub:1},rotationX:12,y:-70});}
if(window.THREE){try{const section=document.querySelector('.signature'),renderer=new THREE.WebGLRenderer({alpha:true,antialias:true});renderer.domElement.className='scene3d';section.appendChild(renderer.domElement);const scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(38,1,.1,100);camera.position.z=9;const object=new THREE.Mesh(new THREE.TorusKnotGeometry(1.6,.42,150,24,2,3),new THREE.MeshStandardMaterial({color:0x5540ef,metalness:.75,roughness:.22}));scene.add(object);scene.add(new THREE.AmbientLight(0xffffff,1.3));const light=new THREE.PointLight(0xff654e,90);light.position.set(4,3,5);scene.add(light);const blue=new THREE.PointLight(0x72c9ff,80);blue.position.set(-4,-2,3);scene.add(blue);function resize3(){const w=section.clientWidth,h=section.clientHeight;renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix()}resize3();addEventListener('resize',resize3);let visible=true;new IntersectionObserver(e=>visible=e[0].isIntersecting).observe(section);function render3(){if(visible){if(!reduce){object.rotation.x+=.003;object.rotation.y+=.005}renderer.render(scene,camera)}requestAnimationFrame(render3)}render3()}catch(e){console.warn('3D unavailable',e)}}
